import yaml,glob,collections
own=collections.Counter(); rows=[]
for f in glob.glob('*.yaml'):
    d=yaml.safe_load(open(f))
    if d['status']!='open': continue
    md=d.get('metadata') or {}
    o=md.get('owner') or d.get('owner') or '(shared)'
    own[o]+=1
    if o!='(shared)': rows.append((o,d['id'],d['kind']))
print('OWNER DISTRIBUTION of open items:')
for k,v in own.most_common(): print(' ',k,v)
print()
for r in sorted(rows): print(' owned:',r)
print()
print('PROTECTION SCOPES:')
for t in ['I-0074','I-0491','I-0492']:
    d=yaml.safe_load(open(t+'.yaml'))
    print(' ',t,'scope=',d.get('scope'),'aud=',repr(d.get('audience')),'labels=',d.get('labels'))
